# exercises: (set, question, solution, hint)   db = enterprise unless set starts with 'nf'
EX = []
def X(s, q, sol, hint='', db='enterprise'):
    EX.append(dict(s=s, q=q, sol=sol.strip(), hint=hint, db=db))

# ---------- week 2: single table
W='w2'
X(W,"Show all details of all projects.","SELECT * FROM projects;")
X(W,"For all projects, show the project name and the number of the supporting department.","SELECT project_name, department_id FROM projects;")
X(W,"Show every project in one column with the header <b>projects with department</b>, like: <i>Debtors is supported by department 3</i>.",
  "SELECT project_name || ' is supported by department ' || department_id AS \"projects with department\" FROM projects;","Glue text with || and give the whole column one alias in double quotes.")
X(W,"Show the name of each family member and how many days old they are.","SELECT name, current_date - birth_date AS days_old FROM family_members;","date − date = number of days.")
X(W,"Show last name, salary and department number of all employees. (Watch the commas!)","SELECT last_name, salary, department_id FROM employees;","<code>salary department_id</code> without comma makes department_id an alias of salary.")
X(W,"List the different places of residence of the employees, without duplicates and in a consistent spelling (initcap).","SELECT DISTINCT INITCAP(location) AS residence FROM employees ORDER BY 1;","'MAASTRICHT' and 'Maastricht' are different values until you convert them.")
X(W,"In which departments do employees work, and where do they live? No duplicate combinations.","SELECT DISTINCT department_id, location FROM employees;")
X(W,"Calculate a 15% discount on 150, with the header <b>discounted</b>.","SELECT 150 * 0.85 AS discounted;","SELECT without FROM.")
X(W,"Which people belong to the family of employee 999111111? Show name, relationship and birth date.","SELECT name, relationship, birth_date FROM family_members WHERE employee_id = '999111111';","employee_id is text, so it needs quotes.")
X(W,"Show all information about the department Administration.","SELECT * FROM departments WHERE UPPER(department_name) = 'ADMINISTRATION';")
X(W,"Show employee_id, last name and location of all employees living in Maastricht, however it's spelled.","SELECT employee_id, last_name, location FROM employees WHERE UPPER(location) = 'MAASTRICHT';","One of them is stored as 'MAASTRICHT'.")
X(W,"Which employees worked between 20 and 35 hours (both included) on project 10? Show employee number, project number and hours.","SELECT employee_id, project_id, hours FROM tasks WHERE project_id = 10 AND hours BETWEEN 20 AND 35;")
X(W,"On which projects did employee 999222222 work less than 10 hours? Show project number and hours.","SELECT project_id, hours FROM tasks WHERE employee_id = '999222222' AND hours < 10;")
X(W,"Which employees are from the province of Groningen (GR) or Noord-Brabant (NB)? Show id, last name and province.","SELECT employee_id, last_name, province FROM employees WHERE province IN ('GR','NB');","Two ways: OR, or IN.")
X(W,"Are there employees called Suzan, Martina, Henk or Douglas, and in which department do they work? Sort by department descending, then first name.","SELECT first_name, last_name, department_id FROM employees WHERE first_name IN ('Suzan','Martina','Henk','Douglas') ORDER BY department_id DESC, first_name;")
X(W,"Show name, department and salary of employees in department 7 earning less than 40000, plus employee 999666666.","SELECT last_name, department_id, salary FROM employees WHERE (department_id = 7 AND salary < 40000) OR employee_id = '999666666';","Brackets around the AND part make it readable.")
X(W,"Which employees live neither in Maarssen nor in Eindhoven? Show last name and location.","SELECT last_name, location FROM employees WHERE UPPER(location) NOT IN ('MAARSSEN','EINDHOVEN');")
X(W,"Show all tasks sorted by hours ascending, with the NULL hours first.","SELECT * FROM tasks ORDER BY hours ASC NULLS FIRST;")
X(W,"Show all tasks sorted by hours descending, with the NULL hours last.","SELECT * FROM tasks ORDER BY hours DESC NULLS LAST;","With DESC, NULL comes first by default.")
X(W,"Which employees live in a place starting with M or O and earn more than 30000? Show last name, location and salary.","SELECT last_name, location, salary FROM employees WHERE (UPPER(location) LIKE 'M%' OR UPPER(location) LIKE 'O%') AND salary > 30000;","Brackets around the OR!")
X(W,"Give the names of the family members born in 1988.","SELECT name FROM family_members WHERE birth_date BETWEEN '01-01-1988' AND '31-12-1988';")
X(W,"Which employee(s) have the lowest salary? Show last name and salary.","SELECT last_name, salary FROM employees ORDER BY salary FETCH FIRST 1 ROW WITH TIES;","Several people share the lowest salary: WITH TIES.")
X(W,"Show the 3 oldest employees (last name and birth date).","SELECT last_name, birth_date FROM employees ORDER BY birth_date FETCH FIRST 3 ROWS ONLY;","Oldest = smallest birth date.")
X(W,"Sorted by hours from most to least (ignoring NULL), which employee_ids are on places 4, 5 and 6?","SELECT employee_id, hours FROM tasks WHERE hours IS NOT NULL ORDER BY hours DESC OFFSET 3 ROWS FETCH NEXT 3 ROWS ONLY;")
X(W,"List employees without a manager.","SELECT employee_id, last_name FROM employees WHERE manager_id IS NULL;")
X(W,"Show the tasks for which the hours are not filled in yet.","SELECT * FROM tasks WHERE hours IS NULL;")
X(W,"Show employees whose last name has an 'o' as second letter.","SELECT employee_id, last_name FROM employees WHERE UPPER(last_name) LIKE '_O%';")
X(W,"Show the employees sorted by department (descending) and within that by last name, page 2 when each page holds 3 rows.","SELECT last_name, department_id FROM employees ORDER BY department_id DESC, last_name OFFSET 3 ROWS FETCH NEXT 3 ROWS ONLY;")

# ---------- week 3: functions
W='w3'
X(W,"Give the employee numbers of employees with children under 18 (no duplicates).","SELECT DISTINCT employee_id FROM family_members WHERE relationship IN ('SON','DAUGHTER') AND date_part('year', age(birth_date)) < 18;")
X(W,"Which employees from Eindhoven or Maarssen are older than 30? Show last name, location and age in years.","SELECT last_name, location, date_part('year', age(birth_date)) AS age FROM employees WHERE UPPER(location) IN ('EINDHOVEN','MAARSSEN') AND age(birth_date) > interval '30 years';")
X(W,"Which employees have a partner aged between 35 and 50? Show the employee number and the partner's age in years.","SELECT employee_id, date_part('year', age(birth_date)) AS partner_age FROM family_members WHERE relationship = 'PARTNER' AND date_part('year', age(birth_date)) BETWEEN 35 AND 50;")
X(W,"For each employee, give the retirement date (65th birthday).","SELECT last_name, birth_date, CAST(birth_date + interval '65 years' AS date) AS retirement FROM employees;")
X(W,"Show the birth date of every family member as e.g. <i>14/02/2009</i>.","SELECT name, to_char(birth_date, 'DD/MM/YYYY') AS birth_date FROM family_members;")
X(W,"Show the birth date of every family member as e.g. <i>Saturday 14 February 2009</i> (no extra spaces).","SELECT name, to_char(birth_date, 'FMDay DD FMMonth YYYY') AS birth_date FROM family_members;","FM removes the padding spaces.")
X(W,"Show the full name of each employee (first, infix, last) without using a function. What happens when infix is NULL?","SELECT first_name || ' ' || infix || ' ' || last_name AS full_name FROM employees;","With || a NULL infix makes the whole name NULL.")
X(W,"Show the full name of each employee using CONCAT_WS so a missing infix causes no problem.","SELECT CONCAT_WS(' ', first_name, infix, last_name) AS full_name FROM employees;")
X(W,"Show each employee's street in lowercase, right-padded with '*' to 30 characters.","SELECT RPAD(LOWER(street), 30, '*') AS street FROM employees;")
X(W,"Show each street with a leading 'Z' removed.","SELECT TRIM(LEADING 'Z' FROM street) AS street FROM employees;")
X(W,"List the employees with the letter 'o' in both their first and last name.","SELECT first_name, last_name FROM employees WHERE POSITION('o' IN LOWER(first_name)) > 0 AND POSITION('o' IN LOWER(last_name)) > 0;")
X(W,"List the employees with 'oo' in their last name and no other o's.","SELECT last_name FROM employees WHERE LOWER(last_name) LIKE '%oo%' AND LENGTH(last_name) - LENGTH(REPLACE(LOWER(last_name),'o','')) = 2;","Count o's: length minus length without o's.")
X(W,"Make an email address: first 3 letters of first name + '.' + first 3 of last name + '@kdg.be', all lowercase, without ||.","SELECT LOWER(CONCAT(SUBSTRING(first_name,1,3), '.', SUBSTRING(last_name,1,3), '@kdg.be')) AS email FROM employees;")
X(W,"Show salary per month (salary/12) rounded to 2 decimals, and truncated to whole euros.","SELECT last_name, ROUND(salary/12, 2) AS rounded, TRUNC(salary/12) AS truncated FROM employees;")
X(W,"On which day of the week (name) was each employee born?","SELECT last_name, to_char(birth_date, 'FMDay') AS weekday FROM employees;")
X(W,"Show the position of the first 'o' in each last name, but only names that contain an 'o'.","SELECT last_name, POSITION('o' IN last_name) AS pos FROM employees WHERE POSITION('o' IN last_name) > 0;")
X(W,"Show the last 3 letters of every last name.","SELECT last_name, SUBSTRING(last_name, LENGTH(last_name)-2, 3) AS last3 FROM employees;")
X(W,"How many full months has each department manager been manager (mgr_start_date until today)?","SELECT department_name, date_part('year', age(mgr_start_date))*12 + date_part('month', age(mgr_start_date)) AS months FROM departments;")
X(W,"Show the employees born in the month of July or September.","SELECT last_name, birth_date FROM employees WHERE date_part('month', birth_date) IN (7, 9);")

# ---------- week 4: joins
W='w4'
X(W,"Show every department with its projects: department id and name, project id, name and location (no Cartesian product!).","SELECT d.department_id, d.department_name, p.project_id, p.project_name, p.location FROM departments d JOIN projects p ON (d.department_id = p.department_id);")
X(W,"List all department managers with employee number, last name, salary and parking spot.","SELECT e.employee_id, e.last_name, e.salary, e.parking_spot FROM departments d JOIN employees e ON (d.manager_id = e.employee_id);","Join on departments.manager_id, not on department_id.")
X(W,"List the projects and the employees working on them: project name, project location, employee last name and the employee's department name.","SELECT p.project_name, p.location, e.last_name, d.department_name FROM projects p JOIN tasks t ON (p.project_id = t.project_id) JOIN employees e ON (t.employee_id = e.employee_id) JOIN departments d ON (e.department_id = d.department_id);")
X(W,"Same as the previous one, but only projects located in Eindhoven or supported by department Administration.","SELECT p.project_name, p.location, e.last_name, d.department_name FROM projects p JOIN tasks t ON (p.project_id = t.project_id) JOIN employees e ON (t.employee_id = e.employee_id) JOIN departments d ON (e.department_id = d.department_id) JOIN departments pd ON (p.department_id = pd.department_id) WHERE UPPER(p.location) = 'EINDHOVEN' OR UPPER(pd.department_name) = 'ADMINISTRATION';","The supporting department of the project is a different role than the employee's department: join departments twice.")
X(W,"List employees with their children (SON/DAUGHTER), sorted by employee last name and then child's name.","SELECT e.last_name, f.name, f.relationship FROM employees e JOIN family_members f ON (e.employee_id = f.employee_id) WHERE f.relationship IN ('SON','DAUGHTER') ORDER BY e.last_name, f.name;")
X(W,"Which male employees live somewhere else than employee Jochems? Show last name and location.","SELECT e.last_name, e.location FROM employees e JOIN employees j ON (UPPER(e.location) <> UPPER(j.location)) WHERE j.last_name = 'Jochems' AND e.gender = 'M';")
X(W,"List pairs of employees with their birthday in the same month (each pair once).","SELECT e1.last_name, e2.last_name, date_part('month', e1.birth_date) AS month FROM employees e1 JOIN employees e2 ON (date_part('month', e1.birth_date) = date_part('month', e2.birth_date) AND e1.employee_id < e2.employee_id);")
X(W,"Which projects are supported by the same department as project 3? Show all project data.","SELECT p.* FROM projects p3 JOIN projects p ON (p3.department_id = p.department_id) WHERE p3.project_id = 3;")
X(W,"Show the employees for whom Bordoloi is the boss of their boss.","SELECT e.last_name FROM employees e JOIN employees b ON (e.manager_id = b.employee_id) JOIN employees bb ON (b.manager_id = bb.employee_id) WHERE bb.last_name = 'Bordoloi';")
X(W,"Show each employee's last name with the last name of their boss (header <b>boss</b>).","SELECT e.last_name, boss.last_name AS boss FROM employees e JOIN employees boss ON (e.manager_id = boss.employee_id);")
X(W,"Who earns more than Bock? Show last name and salary.","SELECT e.last_name, e.salary FROM employees e JOIN employees b ON (b.salary < e.salary) WHERE b.last_name = 'Bock';")
X(W,"Which employees (last name + hours) worked more hours on project 2 than Bock?","SELECT e.last_name, t.hours FROM employees b JOIN tasks tb ON (b.employee_id = tb.employee_id) JOIN tasks t ON (tb.project_id = t.project_id AND t.hours > tb.hours) JOIN employees e ON (t.employee_id = e.employee_id) WHERE b.last_name = 'Bock' AND tb.project_id = 2;")
X(W,"For each department, show the name and the last name of its manager, with the date they started.","SELECT d.department_name, e.last_name, d.mgr_start_date FROM departments d JOIN employees e ON (d.manager_id = e.employee_id);")
X(W,"Which employees work on a project located in the place where they live? Show last name, location and project name.","SELECT e.last_name, e.location, p.project_name FROM employees e JOIN tasks t ON (e.employee_id = t.employee_id) JOIN projects p ON (t.project_id = p.project_id) WHERE UPPER(e.location) = UPPER(p.location);")
X(W,"Show the departments and all their locations, sorted by department name.","SELECT d.department_name, l.location FROM departments d JOIN locations l ON (d.department_id = l.department_id) ORDER BY d.department_name, l.location;")
X(W,"Which employees work in a department located in their own place of residence? Use USING for the department join.","SELECT last_name, e.location FROM employees e JOIN locations l USING (department_id) WHERE UPPER(e.location) = UPPER(l.location);","Careful: with USING, department_id has no prefix, but location exists in both tables so it needs one.")

# ---------- week 5: aggregates
W='w5'
X(W,"How many hours did employee 999444444 register in total, and on how many tasks are the hours filled in?","SELECT SUM(hours), COUNT(hours) FROM tasks WHERE employee_id = '999444444';","COUNT(hours) skips the NULL.")
X(W,"On how many different projects are people working?","SELECT COUNT(DISTINCT project_id) FROM tasks;")
X(W,"How many hours were spent on average on project 30 (rounded to 1 decimal)?","SELECT ROUND(AVG(hours), 1) FROM tasks WHERE project_id = 30;")
X(W,"How many employees have children?","SELECT COUNT(DISTINCT employee_id) FROM family_members WHERE relationship IN ('SON','DAUGHTER');")
X(W,"What's the highest number of hours spent on project 20?","SELECT MAX(hours) FROM tasks WHERE project_id = 20;")
X(W,"What's the birth date of the youngest child of employee 999111111?","SELECT MAX(birth_date) FROM family_members WHERE employee_id = '999111111' AND relationship IN ('SON','DAUGHTER');","Youngest = most recent date = MAX.")
X(W,"What's the average length of the employees' last names?","SELECT AVG(LENGTH(last_name)) FROM employees;")
X(W,"For each project, give the number of employees working on it.","SELECT project_id, COUNT(*) AS employees FROM tasks GROUP BY project_id ORDER BY project_id;")
X(W,"For each department, give the number of employees from the province of Limburg (LI).","SELECT department_id, COUNT(*) FROM employees WHERE province = 'LI' GROUP BY department_id;")
X(W,"Give the number of subordinates of each manager.","SELECT manager_id, COUNT(*) AS subordinates FROM employees WHERE manager_id IS NOT NULL GROUP BY manager_id;")
X(W,"How many projects does each department support per location?","SELECT department_id, location, COUNT(*) AS projects FROM projects GROUP BY department_id, location ORDER BY department_id, location;")
X(W,"For each department, give the average salary of the employees earning more than 30000.","SELECT department_id, AVG(salary) FROM employees WHERE salary > 30000 GROUP BY department_id;","Per row → WHERE.")
X(W,"Give the average salary of female employees per department, only where that average is higher than 30000.","SELECT department_id, AVG(salary) FROM employees WHERE gender = 'F' GROUP BY department_id HAVING AVG(salary) > 30000;")
X(W,"Show how many sons and how many daughters each employee has, only where an employee has more than one child of the same sex.","SELECT employee_id, relationship, COUNT(*) FROM family_members WHERE relationship IN ('SON','DAUGHTER') GROUP BY employee_id, relationship HAVING COUNT(*) > 1;")
X(W,"For each department, count the female employees earning less than 33000 who have a parking spot.","SELECT department_id, COUNT(*) FROM employees WHERE gender = 'F' AND salary < 33000 AND parking_spot IS NOT NULL GROUP BY department_id;")
X(W,"For each employee (last name), the number of projects they work(ed) on. Only employees with at least one project.","SELECT e.last_name, COUNT(*) AS projects FROM employees e JOIN tasks t ON (e.employee_id = t.employee_id) GROUP BY e.employee_id, e.last_name;")
X(W,"How many projects are there per location, only for Eindhoven and Oegstgeest?","SELECT location, COUNT(project_id) AS number_of_projects FROM projects WHERE UPPER(location) IN ('EINDHOVEN','OEGSTGEEST') GROUP BY location;","Filter rows in WHERE, not in HAVING: it's faster.")
X(W,"Show the departments with more than 2 employees, with their rounded average salary.","SELECT department_id, ROUND(AVG(salary)) AS avg_salary, COUNT(*) FROM employees GROUP BY department_id HAVING COUNT(*) > 2;")
X(W,"Show the highest salary per department, only where it's below 45000.","SELECT department_id, MAX(salary) FROM employees GROUP BY department_id HAVING MAX(salary) < 45000;")
X(W,"List the projects with more than 30 hours in total: <i>3 employees</i> | <i>perform tasks on Debtors</i> | <i>which is supported by dept. Administration</i>, with headers #employees, project, department, sorted by project name.",
  "SELECT COUNT(t.employee_id) || ' employees' AS \"#employees\", 'perform tasks on ' || p.project_name AS project, 'which is supported by dept. ' || d.department_name AS department FROM projects p JOIN tasks t ON (p.project_id = t.project_id) JOIN departments d ON (p.department_id = d.department_id) GROUP BY p.project_name, d.department_name HAVING SUM(t.hours) > 30 ORDER BY p.project_name;","The combo exercise from class.")
X(W,"Give the average of the highest salaries of all departments.","SELECT ROUND(AVG(max_sal)) FROM (SELECT MAX(salary) AS max_sal FROM employees GROUP BY department_id) x;","Subquery in FROM.")
X(W,"Per gender: number of employees, lowest and highest birth date.","SELECT gender, COUNT(*), MIN(birth_date), MAX(birth_date) FROM employees GROUP BY gender;")

# ---------- week 5: outer joins
W='w5o'
X(W,"Show all employees with the names of their family members (also employees without family).","SELECT e.employee_id, e.last_name, f.name, f.relationship FROM employees e LEFT JOIN family_members f ON (e.employee_id = f.employee_id);")
X(W,"Which employees have no family members?","SELECT e.employee_id, e.last_name FROM employees e LEFT JOIN family_members f ON (e.employee_id = f.employee_id) WHERE f.employee_id IS NULL;","Test a column that's never NULL in a real row.")
X(W,"Which employees aren't assigned to any project? First and last name.","SELECT e.first_name, e.last_name FROM employees e LEFT JOIN tasks t ON (e.employee_id = t.employee_id) WHERE t.employee_id IS NULL;")
X(W,"List all departments and the projects they support (if any): department name, project name, location.","SELECT d.department_name, p.project_name, p.location FROM departments d LEFT JOIN projects p ON (d.department_id = p.department_id);")
X(W,"For every employee (all of them), the number of projects. Employees without projects show 0.","SELECT e.last_name, COUNT(t.project_id) AS projects FROM employees e LEFT JOIN tasks t ON (e.employee_id = t.employee_id) GROUP BY e.employee_id, e.last_name;","COUNT(*) would give 1 for the NULL row.")
X(W,"List the employees whose last name starts with G or J, with their department name and their family members' names (if any).","SELECT e.last_name, d.department_name, f.name FROM employees e LEFT JOIN departments d ON (e.department_id = d.department_id) LEFT JOIN family_members f ON (e.employee_id = f.employee_id) WHERE UPPER(e.last_name) LIKE 'G%' OR UPPER(e.last_name) LIKE 'J%';")
X(W,"List employees whose first name starts with B, D, G, L or M, with the projects they work on (if any): last name, first name, project name, hours. Sort by last name and project name.","SELECT e.last_name, e.first_name, p.project_name, t.hours FROM employees e LEFT JOIN tasks t ON (e.employee_id = t.employee_id) LEFT JOIN projects p ON (t.project_id = p.project_id) WHERE SUBSTRING(e.first_name,1,1) IN ('B','D','G','L','M') ORDER BY e.last_name, p.project_name;")
X(W,"List the employees who aren't the manager of any other employee.","SELECT e.last_name FROM employees e LEFT JOIN employees s ON (s.manager_id = e.employee_id) WHERE s.employee_id IS NULL;")
X(W,"Show every employee with the last name of their boss, including the employee without boss.","SELECT e.last_name, b.last_name AS boss FROM employees e LEFT JOIN employees b ON (e.manager_id = b.employee_id);")
X(W,"List the employees who are not the manager of another employee OR who don't have a manager.","SELECT DISTINCT e.last_name FROM employees e LEFT JOIN employees s ON (s.manager_id = e.employee_id) WHERE s.employee_id IS NULL OR e.manager_id IS NULL;")
X(W,"Projects with the total hours worked on them; also projects without any task (total empty).","SELECT p.project_name, SUM(t.hours) AS total FROM projects p LEFT JOIN tasks t ON (p.project_id = t.project_id) GROUP BY p.project_name ORDER BY p.project_name;")

# ---------- mock exam: netflix
N='nf'
def NF(q, sol, hint=''): X(N, q, sol, hint, db='netflix')
NF("List all movies (title, release date) that are not available globally.","SELECT title, release_date FROM movie WHERE available_globally = false;")
NF("Show the movies without a known runtime or release date.","SELECT title FROM movie WHERE runtime IS NULL OR release_date IS NULL;")
NF("Show title and runtime of the movies longer than 2 hours, longest first. Runtime is in minutes.","SELECT title, runtime FROM movie WHERE runtime > 120 ORDER BY runtime DESC;")
NF("Show title and runtime formatted as e.g. <i>2h 18min</i> for every movie with a runtime.","SELECT title, (runtime / 60) || 'h ' || mod(runtime, 60) || 'min' AS duration FROM movie WHERE runtime IS NOT NULL;","Integer division and MOD.")
NF("Which movies have a different original title than the title? Show both.","SELECT title, original_title FROM movie WHERE title <> original_title;")
NF("Show the 3 longest movies; include ties.","SELECT title, runtime FROM movie WHERE runtime IS NOT NULL ORDER BY runtime DESC FETCH FIRST 3 ROWS WITH TIES;")
NF("Show each movie's title and release year, released in 2023 or later.","SELECT title, date_part('year', release_date) AS year FROM movie WHERE release_date >= '01-01-2023';")
NF("Show the release date of every TV show as e.g. <i>17 September 2021</i>.","SELECT title, to_char(release_date, 'FMDD FMMonth YYYY') AS released FROM tv_show;")
NF("How many movies are there per locale? Most first.","SELECT locale, COUNT(*) FROM movie GROUP BY locale ORDER BY 2 DESC;")
NF("Show every season with the title of its TV show.","SELECT t.title AS show, s.title AS season, s.season_number FROM season s JOIN tv_show t ON (s.tv_show_id = t.id);")
NF("How many seasons does each TV show have? Show the title, also shows with 0 seasons.","SELECT t.title, COUNT(s.id) AS seasons FROM tv_show t LEFT JOIN season s ON (t.id = s.tv_show_id) GROUP BY t.title ORDER BY t.title;")
NF("Which TV shows have more than one season? Show title and number of seasons.","SELECT t.title, COUNT(*) AS seasons FROM tv_show t JOIN season s ON (t.id = s.tv_show_id) GROUP BY t.title HAVING COUNT(*) > 1;")
NF("Show the weekly Top-10 entries for movies: movie title, start date, rank. Sort by start date, then rank.","SELECT m.title, v.start_date, v.view_rank FROM view_summary v JOIN movie m ON (v.movie_id = m.id) WHERE v.duration = 'WEEKLY' ORDER BY v.start_date, v.view_rank;")
NF("Which movies have ever been number 1 in a weekly ranking? No duplicates.","SELECT DISTINCT m.title FROM view_summary v JOIN movie m ON (v.movie_id = m.id) WHERE v.view_rank = 1 AND v.duration = 'WEEKLY';")
NF("Total views per movie over all reporting periods, highest first. Only movies with views.","SELECT m.title, SUM(v.views) AS total_views FROM movie m JOIN view_summary v ON (m.id = v.movie_id) GROUP BY m.title HAVING SUM(v.views) IS NOT NULL ORDER BY total_views DESC;")
NF("Show every movie with the number of view_summary records about it, including movies with none.","SELECT m.title, COUNT(v.id) AS records FROM movie m LEFT JOIN view_summary v ON (m.id = v.movie_id) GROUP BY m.title ORDER BY m.title;")
NF("Which movies have no viewing statistics at all?","SELECT m.title FROM movie m LEFT JOIN view_summary v ON (m.id = v.movie_id) WHERE v.id IS NULL;")
NF("For season statistics: TV show title, season title, period start, hours viewed. Only SEMI_ANNUALLY reports.","SELECT t.title AS show, s.title AS season, v.start_date, v.hours_viewed FROM view_summary v JOIN season s ON (v.season_id = s.id) JOIN tv_show t ON (s.tv_show_id = t.id) WHERE v.duration = 'SEMI_ANNUALLY';")
NF("Total hours viewed per TV show (over all its seasons and periods).","SELECT t.title, SUM(v.hours_viewed) AS hours FROM tv_show t JOIN season s ON (t.id = s.tv_show_id) JOIN view_summary v ON (s.id = v.season_id) GROUP BY t.title ORDER BY hours DESC;")
NF("For each reporting duration (WEEKLY / SEMI_ANNUALLY): number of records, average views (rounded) and the latest end date.","SELECT duration, COUNT(*), ROUND(AVG(views)), MAX(end_date) FROM view_summary GROUP BY duration;")
NF("Which weekly records reached the top 5 and spent more than 2 weeks in the top 10? Show id, rank and weeks.","SELECT id, view_rank, cumulative_weeks_in_top10 FROM view_summary WHERE duration = 'WEEKLY' AND view_rank <= 5 AND cumulative_weeks_in_top10 > 2;")
NF("Pairs of movies released in the same year (each pair once): title 1, title 2, year.","SELECT m1.title, m2.title, date_part('year', m1.release_date) AS year FROM movie m1 JOIN movie m2 ON (date_part('year', m1.release_date) = date_part('year', m2.release_date) AND m1.id < m2.id);")
NF("Which movies are longer than Lift? Title and runtime.","SELECT m.title, m.runtime FROM movie m JOIN movie l ON (m.runtime > l.runtime) WHERE l.title = 'Lift';")
NF("Show the number of days each weekly reporting period lasts (id, days).","SELECT id, end_date - start_date + 1 AS days FROM view_summary WHERE duration = 'WEEKLY';")
NF("Show the titles of all seasons in uppercase, without the show name before the colon (e.g. <i>SEASON 1</i>). Only titles containing a colon.","SELECT UPPER(TRIM(SUBSTRING(title, POSITION(':' IN title) + 1))) AS season FROM season WHERE POSITION(':' IN title) > 0;")
NF("Average hours viewed per view, rounded to 2 decimals, for every record with views (id, hours per view).","SELECT id, ROUND(hours_viewed::numeric / views, 2) AS hours_per_view FROM view_summary WHERE views IS NOT NULL;","Cast to numeric, otherwise integer division cuts the decimals.")
